/**
 * Fixed-point trigonometry for the deterministic render path (NFR-02, ADR-010).
 *
 * Angles are degrees, clockwise on screen (y down), 0° along +x (spec 3.4.7), and must be multiples of
 * {@link ANGLE_STEP_DEG} (0.25°). Values are Q16 integers (`× 65536`). The table is committed data
 * (`trig-table.ts`, generated by `scripts/gen-trig-table.mjs` with exact BigInt arithmetic); nothing
 * here calls `Math.sin`/`Math.cos`, and every result is an exact integer.
 * @packageDocumentation
 */

import { RasterError } from './errors.js';
import { checkInts } from './store.js';
import { QUARTER_SIN_Q16 } from './trig-table.js';

/** Fixed-point scale: a Q16 value `v` means `v / 65536`. */
export const Q16 = 65536;

/** Resolution of the trig table in degrees. Every angle passed to this module is a multiple of it. */
export const ANGLE_STEP_DEG = 0.25;

/** Table entries per full turn (`360 / ANGLE_STEP_DEG`). */
export const ANGLE_STEPS = 1440;

const QUARTER = ANGLE_STEPS / 4; // 360 steps = 90°
const HALF = ANGLE_STEPS / 2;

/**
 * Largest `|dx|`, `|dy|` accepted by {@link rotatePoint} / {@link rotatePointQ16} (2^31). Keeps every
 * intermediate product below 2^53, so the integer maths is exact in IEEE doubles.
 */
export const MAX_ROTATE_COORD = 2 ** 31;

/** Full sine table, `SIN[k] = sin(k · 0.25°) · 65536`, built from the quarter wave by exact symmetry. */
const SIN = new Int32Array(ANGLE_STEPS);
for (let k = 0; k < ANGLE_STEPS; k++) {
  // sin(180° - x) = sin(x) and sin(180° + x) = -sin(x): integer index maths only.
  const m = k % HALF;
  const v = QUARTER_SIN_Q16[m <= QUARTER ? m : HALF - m] ?? 0;
  SIN[k] = k < HALF ? v : -v;
}

/**
 * Converts an angle in degrees to its table step in `0..1439` (`deg / 0.25`, reduced modulo a full
 * turn; negative angles wrap, `-0` is `0`). Throws `RasterError('BAD_VALUE')` if `deg` is not a finite
 * multiple of 0.25° (with `|deg · 4| ≤ 2^53`). Multiplying by 4 is exact in binary floating point, so
 * the test is exact too.
 */
export function angleToStep(deg: number): number {
  const q = deg * 4;
  if (!Number.isSafeInteger(q)) {
    throw new RasterError(
      'BAD_VALUE',
      `angle must be a finite multiple of ${String(ANGLE_STEP_DEG)} degrees, got ${String(deg)}`,
    );
  }
  const k = q % ANGLE_STEPS;
  return k < 0 ? k + ANGLE_STEPS : k + 0; // `+ 0` turns -0 into 0
}

/** @internal `sin` by table step (any integer step; reduced modulo 1440). */
export function sinStepQ16(step: number): number {
  const k = step % ANGLE_STEPS;
  return SIN[k < 0 ? k + ANGLE_STEPS : k] ?? 0;
}

/** @internal `cos` by table step: `cos(x) = sin(x + 90°)`. */
export function cosStepQ16(step: number): number {
  return sinStepQ16(step + QUARTER);
}

/**
 * `round(sin(deg) · 65536)`, rounded half away from zero, from the committed table. Exact at the
 * quadrant angles and at 30°/150°/210°/330° (`±32768`). `deg` must be a multiple of 0.25°
 * (`RasterError('BAD_VALUE')` otherwise). Identities hold exactly: `sin(-x) = -sin(x)`,
 * `sin(180° - x) = sin(x)`, `sin(x + 360°) = sin(x)`.
 */
export function sinQ16(deg: number): number {
  return sinStepQ16(angleToStep(deg));
}

/**
 * `round(cos(deg) · 65536)`, rounded half away from zero; `cosQ16(x) === sinQ16(x + 90)` exactly.
 * `deg` must be a multiple of 0.25° (`RasterError('BAD_VALUE')` otherwise).
 */
export function cosQ16(deg: number): number {
  return cosStepQ16(angleToStep(deg));
}

/**
 * Largest `|v|` accepted by {@link roundQ16}: `2^53 − 32768`. The rounding computes `v + 32768` (or
 * `32768 − v`), which must be an exactly representable integer, i.e. at most `2^53`; dividing by 65536
 * is then an exact exponent shift and `Math.floor` is exact. One more (`2^53 − 32767`) already sums to
 * `2^53 + 1`, which rounds to even and gives a wrong result, so this bound is tight.
 */
export const MAX_ROUND_Q16 = 2 ** 53 - 32768;

/**
 * @internal Round half away from zero of the Q16 value `v / 65536`, with **no validation**. Exact for
 * integers with `|v| ≤` {@link MAX_ROUND_Q16}; the hot loops of `rotate.ts` use it on products that
 * the {@link MAX_ROTATE_COORD}-style bounds already keep far below that. Returns `0`, never `-0`.
 */
export function roundHalfAwayQ16(v: number): number {
  const r = v >= 0 ? Math.floor((v + 32768) / Q16) : -Math.floor((32768 - v) / Q16);
  return r + 0; // -0 -> 0
}

/**
 * Rounds a Q16 value to the nearest integer, **half away from zero**: `roundQ16(32768) = 1`,
 * `roundQ16(-32768) = -1`, `roundQ16(32767) = 0`. `v` must be an integer with `|v| ≤`
 * {@link MAX_ROUND_Q16} (`2^53 − 32768`, the exact limit of the maths); `RasterError('NON_INTEGER')` /
 * `RasterError('BAD_VALUE')` otherwise.
 */
export function roundQ16(v: number): number {
  checkInts('Q16 value', v);
  if (Math.abs(v) > MAX_ROUND_Q16) {
    throw new RasterError(
      'BAD_VALUE',
      `Q16 value ${String(v)} exceeds ±${String(MAX_ROUND_Q16)} (2^53 - 32768)`,
    );
  }
  return roundHalfAwayQ16(v);
}

function checkCoord(dx: number, dy: number): void {
  checkInts('offset', dx, dy);
  if (Math.abs(dx) > MAX_ROTATE_COORD || Math.abs(dy) > MAX_ROTATE_COORD) {
    throw new RasterError(
      'BAD_VALUE',
      `offset (${String(dx)}, ${String(dy)}) exceeds ±${String(MAX_ROTATE_COORD)}`,
    );
  }
}

/**
 * Rotates the integer vector `(dx, dy)` clockwise on screen (y down) by `deg`, exactly in Q16:
 * `[C·dx − S·dy, S·dx + C·dy]` with `C = cosQ16(deg)`, `S = sinQ16(deg)`. The result is in units of
 * 1/65536 of the input unit (pixels in, Q16 pixels out), with no rounding at all; use it for sub-pixel
 * work (T3.1) and round with {@link roundQ16}. `(1, 0)` at 90° gives `[0, 65536]` (pointing down).
 * `dx`, `dy` are integers with magnitude at most {@link MAX_ROTATE_COORD}.
 */
export function rotatePointQ16(dx: number, dy: number, deg: number): [number, number] {
  checkCoord(dx, dy);
  const k = angleToStep(deg);
  const c = cosStepQ16(k);
  const s = sinStepQ16(k);
  return [c * dx - s * dy + 0, s * dx + c * dy + 0];
}

/**
 * Rotates the integer vector `(dx, dy)` clockwise on screen by `deg` and rounds each coordinate
 * **half away from zero**: `roundQ16` of {@link rotatePointQ16}. This is the snapping primitive of
 * FR-RIG-20 step 2 (`childPivot = parentSnapped + rotatePoint(rest, θq)`). Deterministic: integer maths
 * on the committed table only. It agrees with a float64 `round(dx·cos θ − dy·sin θ)` except where the
 * true value lies within the table's quantisation error (`(|dx| + |dy|) / 131072`) of a `.5` boundary,
 * exact ties included (e.g. `(1, 0)` at 30° is exactly `(0.866…, 0.5)` in Q16 and gives `[1, 1]`).
 */
export function rotatePoint(dx: number, dy: number, deg: number): [number, number] {
  const [x, y] = rotatePointQ16(dx, dy, deg);
  return [roundQ16(x), roundQ16(y)];
}
